import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { STATUSES, statusCount, useClaims } from '../claims/claims';
import { type Person, usePeople } from '../people/people';
import { usePersonDue, useSheetDueTotal } from '../rates/due.slot';
import { dueTotal } from '../rates/rates';
import { crewDue, useCrews } from '../crews/crews';
import { useOverdue, useSheetOverdue } from '../overdue/overdue.slot';
import { useFigure } from '../locale/locale';

/** Names are compared ignoring case and the spaces around them. */
const nameKey = (name: string) => name.trim().toLowerCase();

/** The person on the sheet with the user's name, by name or alias (undefined when none). */
function personNamed(people: Person[] | undefined, user: string): Person | undefined {
  const key = nameKey(user);
  if (key === '') return undefined;
  return (people ?? []).find((p) => nameKey(p.name) === key || p.aliases.some((a) => nameKey(a) === key));
}

// The sheet's counters, always in the header: its people (retired people included), its claims per
// status (the summary's counts) and its due- and overdue-totals (the rollup's), from the same figures;
// then the signed-in user's own due- and overdue-totals (their person's, blank when no person has their name),
// and their crew total: the due-totals of the crews their person leads, added up (blank when they lead none).
function HeaderCounters() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const due = useSheetDueTotal();
  const overdue = useSheetOverdue();
  const [user] = useCurrentUser();
  const me = personNamed(people.data, user);
  const myDue = usePersonDue();
  const myOverdue = useOverdue();
  const crews = useCrews(sheet);
  const led = me ? (crews.data ?? []).filter((c) => c.leadId === me.id) : [];
  const myCrewDue = led.length > 0 ? dueTotal(led.map((c) => crewDue(c, people.data ?? [], myDue))) : '';

  return (
    <p data-testid="header-counters">
      People <strong data-testid="header-people-count">{(people.data ?? []).length}</strong>{' '}
      {STATUSES.map((s) => (
        <span key={s}>
          {s} <strong data-testid={`header-claims-${s}-count`}>{statusCount(claims.data, s)}</strong>{' '}
        </span>
      ))}
      Due total <strong data-testid="header-due-total">{fig(due)}</strong>{' '}
      Overdue total <strong data-testid="header-overdue-total">{fig(overdue.total)}</strong>{' '}
      My due total <strong data-testid="my-due-total">{fig(me ? myDue(me) : '')}</strong>{' '}
      My overdue total <strong data-testid="my-overdue-total">{fig(me ? myOverdue(me).total : '')}</strong>{' '}
      My crew total <strong data-testid="my-crew-due-total">{fig(myCrewDue)}</strong>
    </p>
  );
}

export const contribution = AppHeader.fill({ order: 30, Component: HeaderCounters });
import { type Claim, isOpen } from '../claims/claims';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import { type Settings, graceOf, latePctOf, roundingOf } from '../settings/settings';
import { type Grades, type Person, gradeOn } from '../people/people';

const DAY = 24 * 60 * 60 * 1000;

/** The claim's due-by (yyyy-MM-dd): fixed when it was added, from the terms of its person's grade then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/** The date (yyyy-MM-dd) the claim's overdue counts from: its due-by plus the grace days in force on its date for
 *  its person's grade then (its due-by when none, or when the late charge is not known). */
export const graceBy = (claim: Claim, late?: Late): string => late?.graceBy?.(claim) ?? dueBy(claim);

/** Whether the claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus any grace is before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined, late?: Late): boolean {
  return isOpen(claim) && !claim.deferred && today !== undefined && graceBy(claim, late) < today;
}

/** The date `days` after the date (yyyy-MM-dd). */
const plusDays = (date: string, days: number): string =>
  new Date(Date.parse(`${date}T00:00:00Z`) + days * DAY).toISOString().slice(0, 10);

/** Whether the claim is review-late: it is REVIEW and its review day plus the sheet's review SLA (whole days; null or
 *  blank for none) is before the sheet's today. */
export function reviewLate(claim: Claim, today: string | undefined, sla: string | null | undefined): boolean {
  return claim.status === 'REVIEW' && claim.reviewOn !== null && today !== undefined && sla != null && sla !== ''
    && plusDays(claim.reviewOn, Number(sla)) < today;
}

/** How many full 30 days the claim is overdue on the sheet's today, counted from its due-by plus any grace (0 when it is not overdue). */
export function latePeriods(claim: Claim, today: string | undefined, late?: Late): number {
  if (today === undefined || !overdue(claim, today, late)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${graceBy(claim, late)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** The 30-day boundaries (yyyy-MM-dd) the claim is overdue past on the sheet's today: its due-by plus any grace, plus 30, 60, 90 ... days. */
export function lateBoundaries(claim: Claim, today: string | undefined, late?: Late): string[] {
  const start = Date.parse(`${graceBy(claim, late)}T00:00:00Z`);
  return Array.from({ length: latePeriods(claim, today, late) }, (_, i) =>
    new Date(start + (i + 1) * 30 * DAY).toISOString().slice(0, 10));
}

/** What the sheet's late charge follows: its late percent in force on each boundary date, each claim's due-by plus
 *  the grace days in force on its date for its person's grade then (of these people), and its today; and how it rounds:
 *  a claim rounding by a date with a rounding mode in force rounds by it, else one rounding by a date before the policy
 *  date (else the sheet's today) rounds half up. */
export function lateOf(settings: Settings | undefined, today: string | undefined, people: Person[] | undefined): Late {
  const policy = settings?.policyDate ?? today;
  const pcts = latePctOf(settings);
  const roundings = roundingOf(settings);
  const graces = graceOf(settings);
  const late: Late = {
    pct: pcts,
    boundaries: (c) => lateBoundaries(c, today, late),
    halfUp: (c) => {
      const mode = roundings?.(c.roundsBy ?? c.date);
      if (mode === 'half-up' || mode === 'half-even') return mode === 'half-up';
      return policy !== undefined && (c.roundsBy ?? c.date) < policy;
    },
    graceBy: (c) => {
      const person = people?.find((p) => p.id === c.personId);
      const grace = person && graces?.(gradeOn(person.grades, c.date), c.date);
      return grace == null ? dueBy(c) : plusDays(dueBy(c), grace);
    },
  };
  return late;
}

/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: Floor,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, today, lateCharge));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { counts, live, useClaims } from '../claims/claims';
import { floorOf, useSettings } from '../settings/settings';
import { trimmedTotal, useRates } from '../rates/rates';
import { lateOf, overdueFigures } from './overdue';
import { useFigure } from '../locale/locale';
import { useColumnShown } from '../columns/columns';

// A person's overdue count and overdue-total (the due of their overdue claims that count), and the sheet's.
function OverdueHead() {
  const shown = useColumnShown();
  return (
    <>
      {shown('overdue-count') && <th>Overdue</th>}
      {shown('overdue-total') && <th>Overdue total</th>}
    </>
  );
}

/** A person's overdue figures on the sheet (the current sheet's unless another is named). */
export function useOverdue(of?: string) {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  return (person: Person) =>
    overdueFigures(
      live((claims.data ?? []).filter((c) => c.personId === person.id), [person]).filter(counts),
      rates.data,
      person.grades,
      floorOf(settings),
      today,
      lateOf(settings, today, [person]),
    );
}

function PersonOverdue({ person }: { person: Person }) {
  const fig = useFigure();
  const { count, total } = useOverdue()(person);
  const shown = useColumnShown();
  return (
    <>
      {shown('overdue-count') && <td data-testid="person-overdue-count">{count}</td>}
      {shown('overdue-total') && <td data-testid="person-overdue-total">{fig(total)}</td>}
    </>
  );
}

/** The sheet's overdue figures (the current sheet's unless another is named): everyone's overdue counts
 *  added up, and their overdue-totals added up trimmed of the single highest and lowest when three or more
 *  people have one. */
export function useSheetOverdue(of?: string): { count: number; total: string } {
  const [current] = useCurrentSheet();
  const sheet = of ?? current;
  const people = usePeople(sheet);
  const figures = (people.data ?? []).map(useOverdue(sheet));
  return { count: figures.reduce((n, f) => n + f.count, 0), total: trimmedTotal(figures.map((f) => f.total)) };
}

function OverdueTotal() {
  const fig = useFigure();
  const { count, total } = useSheetOverdue();
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{fig(total)}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: OverdueHead }),
  PersonColumns.fill({ order: 17, Component: PersonOverdue }),
  HomeMain.fill({ order: 36, Component: OverdueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A user name's role on the sheet. A name with none assigned is a clerk; a viewer may change nothing. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward', 'viewer'] as const;

/** Under the sheet's key, so loading the sheet again re-reads its roles. */
export const rolesKey = (sheet: string) => [...sheetKey(sheet), 'roles'] as const;

export function useRoles(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(rolesKey(sheet), asOf),
    queryFn: () => getJson<Role[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/roles`, asOf)),
    enabled: sheet !== '',
  });
}

/** The steward role delegated to `user` by the steward `by` for from..to (yyyy-mm-dd), inclusive. */
export type Delegation = { user: string; from: string; to: string; by: string };

export const delegationsKey = (sheet: string) => [...sheetKey(sheet), 'delegations'] as const;

export function useDelegations(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(delegationsKey(sheet), asOf),
    queryFn: () => getJson<Delegation[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/delegations`, asOf)),
    enabled: sheet !== '',
  });
}
