    /** Every role assigned on the sheet, by user name. */
    public List<RoleResponse> list(String sheetId) {
        return listFrom(sheetId, "sheet_role");
    }

    /** Every role assigned on the sheet at the end of the date (see {@link History}), by user name. */
    public List<RoleResponse> listAsOf(String sheetId, LocalDate date) {
        return listFrom(sheetId, History.asOf("sheet_role", "sheet_id, user_name", date));
    }

    private List<RoleResponse> listFrom(String sheetId, String table) {
        return jdbc.query("SELECT user_name, role FROM " + table + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).shown()),
                sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force, else
     *  the role assigned. */
    public Role find(String sheetId, String user) {
        return delegations.delegator(sheetId, user) != null ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's role as assigned on the sheet, delegations aside: clerk unless assigned otherwise. */
    public Role assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}
    /** Every delegation on the sheet, in the order they were made. */
    public List<Delegation> list(String sheetId) {
        return jdbc.query("SELECT user_name, from_date, to_date, delegated_by FROM delegation WHERE sheet_id = ?"
                + " ORDER BY id", ROW, sheetId);
    }

    /** Every delegation on the sheet at the end of the date (see {@link History}), in the order they were made. */
    public List<Delegation> listAsOf(String sheetId, LocalDate date) {
        return jdbc.query("SELECT user_name, from_date, to_date, delegated_by FROM "
                + History.asOf("delegation", "id", date) + " WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
    }

    /** The steward who delegated to the user a delegation in force on the sheet's today (the latest made
     *  when several are), or null when none is. */
    public String delegator(String sheetId, String user) {
        if (user == null) {
            return null;
        }
        LocalDate today = sheets.today(sheetId);
        List<String> found = jdbc.queryForList("SELECT delegated_by FROM delegation WHERE sheet_id = ?"
                + " AND user_name = ? AND from_date <= ? AND to_date >= ? ORDER BY id DESC", String.class,
                sheetId, user.trim(), today, today);
        return found.isEmpty() ? null : found.get(0);
    }

    public void add(String sheetId, Delegation d) {
        jdbc.update("INSERT INTO delegation (sheet_id, user_name, from_date, to_date, delegated_by)"
                + " VALUES (?, ?, ?, ?, ?)", sheetId, d.user(), d.from(), d.to(), d.by());
import { defineSlot } from '../Slot';

/** The home page's body: the sheet's panels (its people, ...). */
export const HomeMain = defineSlot('home.main');
